function subArrayRanges(nums) {
  const n = nums.length;
  const maxStack = [];
  const minStack = [];
  let total = 0;

  for (let right = 0; right <= n; right++) {
    while (maxStack.length > 0 && (right === n || nums[maxStack[maxStack.length - 1]] < nums[right])) {
      const mid = maxStack.pop();
      const left = maxStack.length > 0 ? maxStack[maxStack.length - 1] : -1;
      total += nums[mid] * (mid - left) * (right - mid);
    }
    while (minStack.length > 0 && (right === n || nums[minStack[minStack.length - 1]] > nums[right])) {
      const mid = minStack.pop();
      const left = minStack.length > 0 ? minStack[minStack.length - 1] : -1;
      total -= nums[mid] * (mid - left) * (right - mid);
    }
    maxStack.push(right);
    minStack.push(right);
  }
  return total;
}

