function subArrayRanges(nums) {
  // Grow every subarray one element at a time, keeping its smallest and largest value.
  let sum = 0;
  for (let start = 0; start < nums.length; start++) {
    let low = nums[start];
    let high = nums[start];
    for (let end = start; end < nums.length; end++) {
      low = Math.min(low, nums[end]);
      high = Math.max(high, nums[end]);
      sum += high - low;
    }
  }
  return sum;
}

