function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 1 + Math.floor(rand() * 8);
  // Shapes: 0 = few distinct values (many ties), 1 = ascending, 2 = descending, 3 = random.
  const shape = Math.floor(rand() * 4);
  const few = [-1000000000, -3, 0, 2, 1000000000];
  const pick = () => {
    if (shape === 0) return large ? few[Math.floor(rand() * few.length)] : Math.floor(rand() * 3);
    if (large) return Math.floor(rand() * 2000000001) - 1000000000;
    if (rand() < 0.1) return rand() < 0.5 ? -1000000000 : 1000000000;
    return Math.floor(rand() * 21) - 10;
  };
  const nums = Array.from({ length: n }, pick);
  if (shape === 1) nums.sort((a, b) => a - b);
  if (shape === 2) nums.sort((a, b) => b - a);
  return [nums];
}
